import { Context, Effect, Layer } from 'effect'
import { RuntimeError } from '@hrbr/runtime-core'

export const RUNTIME_SECRET_REF_FIELD = '__hrbr_secret_ref'

export type RuntimeSecretRefHandle = {
  readonly [RUNTIME_SECRET_REF_FIELD]: string
}

export interface RuntimeSecretRefStoreEntry {
  readonly sourceNamespace: string
  readonly credentialName: string
  readonly encryptedValue: string
}

export interface RuntimeSecretRegistrationInput {
  readonly namespace: string
  readonly name: string
  readonly register: () => Promise<RuntimeSecretRefHandle>
}

export interface RuntimeSecretsProvider {
  readonly registerFromSource: (
    input: RuntimeSecretRegistrationInput
  ) => Effect.Effect<RuntimeSecretRefHandle, RuntimeError>
}

export const RuntimeSecretsProvider = Context.Service<RuntimeSecretsProvider>(
  '@hrbr/runtime-provider-secrets/RuntimeSecretsProvider'
)

export const RuntimeSecretsProviderLive = Layer.succeed(RuntimeSecretsProvider, {
  registerFromSource: (input) =>
    Effect.tryPromise({
      try: input.register,
      catch: (cause) =>
        new RuntimeError('provider', 'Secret provider registration failed', {
          namespace: input.namespace,
          name: input.name,
          cause,
        }),
    }),
})

export function makeRuntimeSecretRefHandle(refId: string): RuntimeSecretRefHandle {
  return { [RUNTIME_SECRET_REF_FIELD]: refId }
}

export function isRuntimeSecretRefHandle(value: unknown): value is RuntimeSecretRefHandle {
  return Boolean(
    value &&
    typeof value === 'object' &&
    typeof (value as Record<string, unknown>)[RUNTIME_SECRET_REF_FIELD] === 'string'
  )
}

export function runtimeSecretRefId(handle: RuntimeSecretRefHandle): string {
  return handle[RUNTIME_SECRET_REF_FIELD]
}

export function normalizeRuntimeSecretName(value: string): string {
  return value.trim().toLowerCase()
}

export function resolveRuntimeSecretSourceLookupNames(
  configValue: string | null,
  requestedName: string
): string[] {
  const names = new Set<string>([requestedName])
  if (!configValue) return [...names]
  try {
    const parsed = JSON.parse(configValue) as {
      kind?: unknown
      sand_secret_bindings?: unknown
    }
    if (parsed.kind !== 'cli' || !Array.isArray(parsed.sand_secret_bindings)) {
      return [...names]
    }
    for (const rawBinding of parsed.sand_secret_bindings) {
      if (!rawBinding || typeof rawBinding !== 'object') continue
      const binding = rawBinding as { secret_name?: unknown; env?: unknown }
      const secretName = typeof binding.secret_name === 'string' ? binding.secret_name : undefined
      const env = typeof binding.env === 'string' ? binding.env : undefined
      if (!secretName) continue
      const requested = normalizeRuntimeSecretName(requestedName)
      if (
        normalizeRuntimeSecretName(secretName) === requested ||
        (env && normalizeRuntimeSecretName(env) === requested)
      ) {
        names.add(secretName)
      }
    }
  } catch {
    return [...names]
  }
  return [...names]
}
